module multi_pipe_8bit
    (clk,rst_n,mul_en_in,mul_a,mul_b,mul_en_out,mul_out);
    input clk;
    input rst_n;
    input mul_en_in;
    input [7:0] mul_a;
    input [7:0] mul_b;
    output reg mul_en_out;
    output reg [15:0] mul_out;

    reg [2:0] mul_en_out_reg;
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;
    wire [15:0] temp [7:0];

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            mul_en_out_reg <= 'd0;
        end
        else begin
            mul_en_out_reg <= {mul_en_out_reg[2:0],mul_en_in};
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            mul_a_reg <= 'd0;
            mul_b_reg <= 'd0;
        end
        else begin
            if(mul_en_in)begin
                mul_a_reg <= mul_a;
                mul_b_reg <= mul_b;
            end
            else begin
                mul_a_reg <= 'd0;
                mul_b_reg <= 'd0;
            end
        end
    end

    assign temp[0] = mul_en_in ? {{8{mul_a_reg[0]}},mul_a_reg[0]} : 'd0;
    assign temp[1] = mul_en_in ? {{8{mul_a_reg[1]}},mul_a_reg[1]} : 'd0;
    assign temp[2] = mul_en_in ? {{8{mul_a_reg[2]}},mul_a_reg[2]} : 'd0;
    assign temp[3] = mul_en_in ? {{8{mul_a_reg[3]}},mul_a_reg[3]} : 'd0;
    assign temp[4] = mul_en_in ? {{8{mul_a_reg[4]}},mul_a_reg[4]} : 'd0;
    assign temp[5] = mul_en_in ? {{8{mul_a_reg[5]}},mul_a_reg[5]} : 'd0;
    assign temp[6] = mul_en_in ? {{8{mul_a_reg[6]}},mul_a_reg[6]} : 'd0;
    assign temp[7] = mul_en_in ? {{8{mul_a_reg[7]}},mul_a_reg[7]} : 'd0;

    reg [15:0] sum [3:0];
    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            sum[0]  <= 'd0;
            sum[1]  <= 'd0;
            sum[2]  <= 'd0;
            sum[3]  <= 'd0;
        end
        else begin
            sum[0]  <= temp[0] + temp[1];
            sum[1]  <= temp[2] + temp[3];
            sum[2]  <= temp[4] + temp[5];
            sum[3]  <= temp[6] + temp[7];
        end
    end

    reg [15:0] mul_out_reg;
    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            mul_out_reg <= 'd0;
        end
        else begin
            mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            mul_en_out <= 'd0;
        end
        else begin
            mul_en_out <= mul_en_out_reg[2];
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n)begin
            mul_out <= 'd0;
        end
        else begin
            if(mul_en_out_reg[2])begin
                mul_out <= mul_out_reg;
            end
            else begin
                mul_out <= 'd0;
            end
        end
    end

endmodule
